contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: depositAmount to deposit into c, withdrawAmount to attempt withdraw, and a bool to choose withdraw vs refund
    function run(uint256 depositAmount, uint256 withdrawAmount, bool doRefund) public payable {
        require(address(this).balance >= depositAmount, "insufficient tester balance");
        // initial deposit into c from this contract
        c.deposit{value: depositAmount}();

        // read observables before action
        uint256 cBalanceBefore = address(c).balance;
        // balances mapping is not public in C, so we cannot read it directly; but C has no getter for balances.
        // However, the contract's behavior for withdraw/refund affects address(c).balance and this contract's balance.
        uint256 myBalanceBefore = address(this).balance;

        bool reverted = false;
        if (doRefund) {
            // refund should transfer the depositor's recorded balance to this contract and set it to zero inside C.
            try c.refund() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // attempt withdraw of withdrawAmount
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read observables after action
        uint256 cBalanceAfter = address(c).balance;
        uint256 myBalanceAfter = address(this).balance;

        // General rule to assert:
        // If the call did not revert, then the sum of balances (contract + this) decreased by exactly 0 (Ether conserved) except that Ether moved from c to this by the exact amount sent; i.e.
        // (myBalanceAfter - myBalanceBefore) == (cBalanceBefore - cBalanceAfter)
        // Additionally, if the call did not revert, the contract's balance after must be <= before.
        // If the call reverted, balances must be unchanged.

        assert(
            // when call succeeded: Ether moved out of c to this by same amount
            (!reverted && (myBalanceAfter - myBalanceBefore == cBalanceBefore - cBalanceAfter) && cBalanceAfter <= cBalanceBefore)
            // when call reverted: no net Ether moved between c and this
            || (reverted && myBalanceAfter == myBalanceBefore && cBalanceAfter == cBalanceBefore)
        );
    }

    // allow receiving Ether from C.transfer
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: deposit amount to send to c, withdraw amount to attempt, and a flag chooseRefund to call refund() instead of withdraw()
    function run(uint256 depositAmount, uint256 withdrawAmount, bool chooseRefund) public payable {
        require(address(this).balance >= depositAmount, "insufficient tester balance");

        // make an initial deposit into c
        c.deposit{value: depositAmount}();

        // observe balances before the action
        uint256 cBalanceBefore = address(c).balance;
        uint256 myBalanceBefore = address(this).balance;

        // perform either withdraw or refund as a top-level statement and capture whether it reverted
        bool reverted;
        if (chooseRefund) {
            try c.refund() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe balances after the action
        uint256 cBalanceAfter = address(c).balance;
        uint256 myBalanceAfter = address(this).balance;

        // General invariant:
        // - If the call succeeded, the exact decrease of c's balance equals the exact increase of this contract's balance.
        // - If the call reverted, neither observable balance changed.
        assert((!reverted && (cBalanceBefore - cBalanceAfter == myBalanceAfter - myBalanceBefore) && cBalanceAfter <= cBalanceBefore)
               || (reverted && cBalanceAfter == cBalanceBefore && myBalanceAfter == myBalanceBefore));
    }

    // allow receiving Ether from C.transfer
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: deposit amount to send to c, withdraw amount to attempt
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure this contract has funds to deposit
        require(address(this).balance >= depositAmount);

        // initial deposit into c (top-level state-changing call)
        c.deposit{value: depositAmount}();

        // observe before-values
        uint256 cBalanceBefore = address(c).balance;
        uint256 visibleBefore = c.balances(address(this));

        // attempt withdraw as a top-level call and record whether it reverted
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 cBalanceAfter = address(c).balance;
        uint256 visibleAfter = c.balances(address(this));

        // General rule:
        // - If withdraw reverted: contract balance and visible mapping unchanged.
        // - If withdraw succeeded: contract balance decreased by exactly the amount transferred to this tester
        //   (observable as cBalanceBefore - cBalanceAfter), and the recorded visible balance decreased by at least withdrawAmount
        //   (i.e., visibleBefore >= visibleAfter and visibleBefore - visibleAfter >= withdrawAmount).
        // Note: we avoid underflow by using relational checks rather than subtracting in the asserted branch that might underflow.
        assert(
            (reverted && cBalanceAfter == cBalanceBefore && visibleAfter == visibleBefore)
            || (
                !reverted
                && cBalanceAfter <= cBalanceBefore
                && visibleBefore >= visibleAfter
                && (visibleBefore - visibleAfter) >= withdrawAmount
            )
        );
    }

    // allow receiving Ether from C.transfer
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: deposit some Ether, then attempt withdraw; observe contract balance only via address(c).balance
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure this contract has funds to deposit
        require(address(this).balance >= depositAmount);

        // deposit into c
        c.deposit{value: depositAmount}();

        // observe before-values
        uint256 cBalanceBefore = address(c).balance;

        // attempt withdraw and record whether it reverted
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-value
        uint256 cBalanceAfter = address(c).balance;

        // General rule expressed over observable balances and revert flag:
        // - If withdraw reverted: contract balance unchanged.
        // - If withdraw succeeded: contract balance did not increase, and the decrease is at most withdrawAmount.
        // (We avoid underflow by comparing rather than subtracting when reverted might be true.)
        assert(
            (reverted && cBalanceAfter == cBalanceBefore)
            || (
                !reverted
                && cBalanceAfter <= cBalanceBefore
                && (cBalanceBefore - cBalanceAfter) <= withdrawAmount
            )
        );
    }

    // allow receiving Ether from C.transfer
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address payable other;

    constructor(C _c) { c = _c; other = payable(address(0x1234)); }

    // We take three params: an amount to deposit into C, and a boolean flag useMigrate which decides
    // whether we call migrateTo as the creator (this contract) or attempt it from a non-creator by using
    // a delegate-like approach: we only can call as this contract, so to simulate a non-creator we
    // call migrateTo with an address that is not creator; the contract itself enforces msg.sender==creator.
    // The important observable is address(c).balance before and after and whether migrateTo reverted.
    function run(uint256 depositAmount, address payable to, bool callAsCreator) public payable {
        // ensure funds for deposit
        require(address(this).balance >= depositAmount);

        // Deposit into c so it has non-zero balance (deposit may assert on overflow; avoid causing overflow by
        // keeping depositAmount arbitrary since balances start at 0 and this contract hasn't deposited yet).
        c.deposit{value: depositAmount}();

        uint256 balanceBefore = address(c).balance;

        bool reverted;
        // If callAsCreator == true, call migrateTo as creator (this contract is creator since it deployed c per checker note).
        // If false, attempt migrateTo but it will still be called by this contract; the contract checks creator==msg.sender, so
        // calling migrateTo when this contract is the creator will succeed; to test non-creator behavior we instead
        // pass an arbitrary 'to' but that doesn't change msg.sender; since we cannot change msg.sender, we interpret
        // callAsCreator==false as expecting a revert (this will hold only if this contract is not the creator). To make the
        // property concrete and checkable across both cases, we capture whether it reverted.
        try c.migrateTo(to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;

        // General rule:
        // - If migrateTo reverted: contract balance unchanged.
        // - If migrateTo succeeded: contract balance becomes zero (entire balance forwarded).
        assert(
            (reverted && balanceAfter == balanceBefore)
            || (!reverted && balanceAfter == 0)
        );
    }

    // allow receiving Ether from C.transfer
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We run three operations parameterized: an initial deposit amount, then withdraw amount, then call refund.
    // The rule: after these operations, the Ether that this test contract holds plus the observable remaining balance in c for this caller
    // (inferred by attempting to withdraw the remaining balance) equals the prior total (conservation of Ether between c and this contract for this address).
    // We cannot read private balances directly; instead we observe effects via successful withdraw/transfer and address balances.

    function run(uint256 depositAmt, uint256 withdrawAmt, uint256 dummy) public payable {
        require(address(this).balance >= depositAmt);
        // record starting balances
        uint256 beforeTester = address(this).balance;
        uint256 beforeContract = address(c).balance;

        // 1) deposit depositAmt into c from this contract
        c.deposit{value: depositAmt}();

        // 2) try to withdraw withdrawAmt; record whether it reverted
        bool withdrew;
        uint256 afterTesterAfterWithdraw;
        try c.withdraw(withdrawAmt) {
            withdrew = true;
            afterTesterAfterWithdraw = address(this).balance;
        } catch {
            withdrew = false;
            afterTesterAfterWithdraw = address(this).balance;
        }

        // 3) call refund (which sends all this caller's recorded balance back)
        bool refunded;
        uint256 afterTesterAfterRefund;
        try c.refund() {
            refunded = true;
            afterTesterAfterRefund = address(this).balance;
        } catch {
            refunded = false;
            afterTesterAfterRefund = address(this).balance;
        }

        // After these operations, the total Ether owned by this tester plus Ether held by c
        // should equal the initial total plus any external transfers that might have happened.
        // Since only this tester interacted, and c only transfers to this tester (or to migrate target by creator which isn't invoked),
        // Ether cannot be created: (beforeTester + beforeContract) == (afterTesterAfterRefund + address(c).balance)
        // Because of possible reverts in intermediate steps, we express the equality as using the observed final values.

        assert(beforeTester + beforeContract == afterTesterAfterRefund + address(c).balance);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to deposit some amount (safe: only if this contract has funds), then try a withdraw of 'w'.
    // Rule: If withdraw(call) does not revert, then address(this) increases by exactly the withdrawn amount and address(c).balance decreases by at least that amount.
    // We observe balances before/after and whether withdraw reverted.
    function run(uint256 depositAmt, uint256 w) public payable {
        require(address(this).balance >= depositAmt);

        // Record balances before any interaction
        uint256 beforeTester = address(this).balance;
        uint256 beforeContract = address(c).balance;

        // If depositAmt > 0, perform deposit to set up balance in c for this caller.
        if (depositAmt > 0) {
            c.deposit{value: depositAmt}();
        }

        // Record balances after deposit
        uint256 midTester = address(this).balance;
        uint256 midContract = address(c).balance;

        // Try to withdraw w and observe whether it reverts and the resulting balances
        bool withdrew;
        uint256 afterTester;
        uint256 afterContract;
        try c.withdraw(w) {
            withdrew = true;
            afterTester = address(this).balance;
            afterContract = address(c).balance;
        } catch {
            withdrew = false;
            afterTester = address(this).balance;
            afterContract = address(c).balance;
        }

        // If withdraw succeeded, then the tester's balance must have increased by exactly w
        // and the contract's balance must have decreased by at least w (it might have decreased more if other transfers occurred,
        // but in this single-transaction setting only transfers from c to this tester should affect it, so we require at least w).
        assert(!withdrew || (afterTester == midTester + w && midContract >= afterContract + w));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take depositAmt to fund c (if desired) and w as the withdraw attempt.
    // All state-changing calls on c are top-level statements.
    function run(uint256 depositAmt, uint256 w) public payable {
        require(address(this).balance >= depositAmt);

        // record balances before any interaction
        uint256 beforeTester = address(this).balance;
        uint256 beforeContract = address(c).balance;

        // If desired, deposit into c so withdraw might succeed.
        if (depositAmt > 0) {
            c.deposit{value: depositAmt}();
        }

        // record balances after deposit (or same as before if no deposit)
        uint256 midTester = address(this).balance;
        uint256 midContract = address(c).balance;

        // Attempt withdraw and observe whether it reverts.
        bool withdrew;
        // We must perform the call as a top-level statement. Use try/catch to detect revert.
        try c.withdraw(w) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        uint256 afterTester = address(this).balance;
        uint256 afterContract = address(c).balance;

        // If withdraw succeeded then this contract's balance increased by exactly w
        // and c's balance decreased by exactly w.
        assert(!withdrew || (afterTester == midTester + w && midContract == afterContract + w));
    }

    // Accept ETH sent from c during withdraw/refund
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take depositAmt to optionally fund c from this contract, so refund can later send ETH back.
    // All state-changing calls on c are top-level statements as required.
    function run(uint256 depositAmt) public payable {
        require(address(this).balance >= depositAmt);

        // Optionally deposit to C so that balances[this] > 0 and refund might send Ether.
        if (depositAmt > 0) {
            c.deposit{value: depositAmt}();
        }

        // Observe balances immediately before calling refund.
        uint256 beforeTester = address(this).balance;
        uint256 beforeContract = address(c).balance;

        // We cannot read balances mapping directly; instead we infer the amount that refund will try to send
        // by calling refund and detecting success and comparing balances before/after.
        bool refunded;
        try c.refund() {
            refunded = true;
        } catch {
            refunded = false;
        }

        uint256 afterTester = address(this).balance;
        uint256 afterContract = address(c).balance;

        // If refund succeeded then the tester's balance increased by exactly the amount that c's balance decreased by,
        // and that amount equals the change in this contract's balance (i.e., Ether moved from c to this contract).
        // This asserts conservation of ETH for a successful refund call for this caller.
        assert(!refunded || (afterTester == beforeTester + (beforeContract - afterContract) && beforeContract >= afterContract));
    }

    receive() external payable {}
}

