contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: deposit some Ether into c on behalf of this contract, then attempt withdraw(amount).
    // Parameters: depositAmt to deposit, withdrawAmt to try to withdraw (both in wei).
    function run(uint256 depositAmt, uint256 withdrawAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");
        // Deposit into c from this contract
        c.deposit{value: depositAmt}();

        // Read recorded balance for this contract (via auto getter) before withdraw
        uint256 beforeBalRecorded = c.balances(address(this));
        // Read external balances
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;

        bool reverted;
        try c.withdraw(withdrawAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalRecorded = c.balances(address(this));
        uint256 afterThis = address(this).balance;
        uint256 afterC = address(c).balance;

        // If withdraw did not revert then: withdrawAmt <= beforeBalRecorded, recorded balance decreased by withdrawAmt,
        // this contract's external balance increased by withdrawAmt, and contract balance decreased by withdrawAmt.
        assert(reverted || (
            withdrawAmt <= beforeBalRecorded &&
            afterBalRecorded + withdrawAmt == beforeBalRecorded &&
            afterThis == beforeThis + withdrawAmt &&
            afterC + withdrawAmt == beforeC
        ));
    }

    // Allow receiving Ether back from C
    receive() external payable {}
}

