contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params: depositAmt to deposit into c, ensure we have that Ether available
    // Then call refund and check effects.
    function run(uint256 depositAmt) public payable {
        // Need Ether to deposit into c
        require(address(this).balance >= depositAmt, "insufficient test balance for deposit");

        // Deposit into c from this contract
        c.deposit{value: depositAmt}();

        // Record balances before refund
        uint256 beforeThis = address(this).balance;
        uint256 beforeC = address(c).balance;
        uint256 recordedBefore = c.balances(address(this));

        bool reverted;
        try c.refund() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterThis = address(this).balance;
        uint256 afterC = address(c).balance;
        uint256 recordedAfter = c.balances(address(this));

        // If refund did not revert, then recorded balance for this caller becomes zero,
        // and Ether moved: this gained exactly recordedBefore and c lost exactly recordedBefore.
        // If refund reverted, no guarantees (we allow revert).
        assert(reverted || (recordedBefore > 0 && recordedAfter == 0 && afterThis == beforeThis + recordedBefore && afterC + recordedBefore == beforeC));
    }

    receive() external payable {}
}

