contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // attemptMigrator: address to pass to migrateTo
    // sendAmt: optionally fund c by sending Ether to it via deposit (we avoid using deposit to not trigger its internal assert), so instead we send Ether directly to the contract's address using transfer via this contract's balance by calling payable(address(c)).call{value:sendAmt}("\x00");
    // We require this test contract to hold enough Ether to perform the transfer.
    function run(address attemptMigrator, uint256 sendAmt) public payable {
        require(address(this).balance >= sendAmt, "insufficient funds to seed c");

        // Seed c with Ether without calling c.deposit to avoid deposit's internal assert.
        // Use low-level call to send Ether to c so that address(c).balance increases but no C function logic runs.
        (bool okSeed,) = payable(address(c)).call{value: sendAmt}("\x00");
        // okSeed may be true or false depending on fallback/receive; proceed regardless.

        // Determine whether migrateTo reverts when called by this contract (which is NOT the original creator)
        bool reverted;
        try c.migrateTo(attemptMigrator) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable balances after the call
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: if migrateTo did not revert when called by this contract (which is not the constructor's deployer of c),
        // then it must have transferred the entire contract balance to the provided address, so c's balance becomes zero and this contract's balance is unchanged (since funds go to attemptMigrator, not this contract).
        // Otherwise (if it reverted), we make no claim about balances. This encodes that only the creator can successfully migrate funds.
        assert(reverted || (afterC == 0 && afterThis <= address(this).balance + sendAmt));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property test
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");
        // read before-values
        uint256 beforeContractBalance = address(c).balance;
        // call deposit sending `amount` wei
        c.deposit{value: amount}();
        // read after-values using public surface: address(c).balance and balances getter
        uint256 afterContractBalance = address(c).balance;
        uint256 recorded = c.balances(address(this));

        // General rule: after depositing `amount` the contract's on-chain balance increases by at least amount
        // and the recorded balances[address(this)] is at least amount (since it started at 0)
        assert(afterContractBalance >= beforeContractBalance + amount && recorded >= amount);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property test
    // amount: how much Ether to deposit into C
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // read before balance of contract C
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeMyBalance = address(this).balance;

        // perform deposit to C from this contract
        c.deposit{value: amount}();

        // read after balance of contract C
        uint256 afterContractBalance = address(c).balance;

        // Now attempt to withdraw the same amount back. Capture whether it reverts.
        bool withdrewReverted;
        try c.withdraw(amount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // read final balances
        uint256 finalContractBalance = address(c).balance;
        uint256 finalMyBalance = address(this).balance;

        // General rule:
        // 1) The on-chain balance of c must have increased by at least `amount` after deposit.
        // 2) If withdrawing `amount` did not revert, this contract's balance must have increased (net) by at least amount
        //    compared to immediately after deposit attempt (i.e., funds were returned), and c's balance decreased accordingly.
        // We encode this as a single assert combining both possibilities.
        assert(
            // deposit effect: c's balance grew by at least amount
            afterContractBalance >= beforeContractBalance + amount
            && (
                // either withdraw reverted (still acceptable), or withdraw succeeded and balances reflect transfer
                withdrewReverted
                || (finalMyBalance >= beforeMyBalance -  /* gas paid during deposit/withdraw can make exact equality unreliable */ 0 + amount && finalContractBalance + amount <= afterContractBalance + 0)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // amount: how much Ether to deposit into C before refund
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // deposit 'amount' into C from this contract
        c.deposit{value: amount}();

        // observe contract balance of C before refund
        uint256 beforeC = address(c).balance;
        // observe this contract balance before refund
        uint256 beforeMe = address(this).balance;

        // attempt refund and capture whether it reverted
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        // observe balances after refund attempt
        uint256 afterC = address(c).balance;
