contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(uint256 depositAmt, uint256 withdrawAmt, bool doRefund, bool doMigrate, address migrateTo) public payable {
        require(address(this).balance >= depositAmt, "not enough balance to deposit");
        // read initial observable values
        uint256 before_c_bal = address(c).balance;
        uint256 before_my_record = c.balances(address(this));

        // perform a deposit from this contract to c if requested
        if (depositAmt > 0) {
            c.deposit{value: depositAmt}();
        }

        // try withdraw and capture whether it reverted
        bool withdrewReverted;
        try c.withdraw(withdrawAmt) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // optionally call refund and capture revert
        bool refundReverted;
        if (doRefund) {
            try c.refund() {
                refundReverted = false;
            } catch {
                refundReverted = true;
            }
        } else {
            refundReverted = false;
        }

        // optionally try migrateTo (only creator can succeed, so usually reverts)
        bool migrateReverted;
        if (doMigrate) {
            try c.migrateTo(migrateTo) {
                migrateReverted = false;
            } catch {
                migrateReverted = true;
            }
        } else {
            migrateReverted = true; // not invoked → treat as not-successful
        }

        // read final observable values
        uint256 after_c_bal = address(c).balance;
        uint256 after_my_record = c.balances(address(this));

        // General invariant to assert:
        // 1) The total Ether observable (contract balance + recorded balance for this tester)
        //    should equal the initial total plus deposits made by this test (depositAmt)
        //    minus any successful transfers out (withdraw or refund) that left c.
        // However we cannot directly observe internal transfers out other than via the pair of
        // before/after readings. So assert the consistency that the change in address(c).balance
        // equals the change in recorded balance for this tester plus other externally visible
        // effects; equivalently, the sum of after_c_bal + after_my_record == before_c_bal + before_my_record + depositAmt - (if withdraw succeeded then withdrawAmt else 0) - (if refund succeeded then previous balance was transferred)
        // We express a conservative invariant that the sum of c.balance and c.balances(this) only changes by exactly depositAmt when withdraw/refund/migrate did not succeed in draining contract unexpectedly.

        // Compute whether withdraw succeeded (i.e., not reverted and withdrawAmt <= prior recorded balance after deposit)
        bool withdrawSucceeded = !withdrewReverted;
        // Compute whether refund succeeded
        bool refundSucceeded = doRefund && !refundReverted;

        // We assert that if neither migrate nor an external successful draining occurred (migrateReverted==true)
        // then the combined observable total must equal initial total + depositAmt - (withdrawSucceeded ? withdrawAmt : 0) - (refundSucceeded ? (before_my_record + (depositAmt)) : 0 if refund used the then-current balance)
        // To avoid needing the exact refunded amount (which is prior recorded balance), we assert a weaker but general invariant:
        // The combined total after is equal to before plus depositAmt minus the sum of withdrawn amounts that succeeded or refunded amounts that succeeded as visible by reduction in the pair.

        // The following asserts that the net change in the combined observable (after_c_bal + after_my_record) equals the depositAmt
        // minus the visible decrease in the pair (i.e., (before_c_bal + before_my_record) - (after_c_bal + after_my_record)). Rearranged to a tautology that prevents hidden drain: after_sum - before_sum == depositAmt - visible_out
        uint256 before_sum = before_c_bal + before_my_record;
        uint256 after_sum = after_c_bal + after_my_record;

        // visible_out is the amount observed leaving the pair; compute as signed difference but keep unsigned by branching
        uint256 visible_out;
        if (after_sum <= before_sum + depositAmt) {
            visible_out = (before_sum + depositAmt) - after_sum;
        } else {
            // If after_sum > before_sum + depositAmt then unexpected incoming funds arrived (not from this test). Treat as violation by forcing assert false.
            assert(false);
        }

        // Now ensure that any successful withdraw or refund must be accounted for by visible_out (i.e., they cannot have succeeded while visible_out is smaller than the amounts they should have transferred)
        // If withdrawSucceeded then visible_out must be at least withdrawAmt. If refundSucceeded then visible_out must be at least the previous recorded balance (which is <= before_my_record + depositAmt).
        if (withdrawSucceeded) {
            assert(visible_out >= withdrawAmt);
        }
        if (refundSucceeded) {
            // refunded amount cannot exceed the total that was in the pair before the refund, which is before_my_record + depositAmt
            assert(visible_out >= before_my_record + depositAmt);
        }

        // Final single assert required by the harness: combine the conditions into one general rule
        assert(
            // no unexpected external incoming Ether
            after_sum <= before_sum + depositAmt
            // if withdraw succeeded it is reflected in visible_out
            && (!withdrawSucceeded || ((before_sum + depositAmt) - after_sum) >= withdrawAmt)
            // if refund succeeded it is reflected and at least the wallet's previous balance was removed
            && (!refundSucceeded || ((before_sum + depositAmt) - after_sum) >= (before_my_record + depositAmt))
        );
    }

    receive() external payable { }
 }

