    // doMigrate: whether to call migrateTo(to)
    // to: address argument for migrateTo
    function run(uint256 depositAmt, uint256 withdrawAmt, bool doRefund, bool doMigrate, address to) public payable {
        // ensure this test contract has enough balance to send depositAmt
        require(address(this).balance >= depositAmt, "insufficient balance for deposit");

        // observe initial contract balance
        uint256 before_c_bal = address(c).balance;

        // perform deposit if requested
        if (depositAmt > 0) {
            // deposit is payable; send depositAmt
            c.deposit{value: depositAmt}();
        }

        // attempt withdraw and capture whether it reverted
        bool withdrawReverted;
        try c.withdraw(withdrawAmt) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // attempt refund if requested and capture whether it reverted
        bool refundReverted = true;
        if (doRefund) {
            try c.refund() {
                refundReverted = false;
            } catch {
                refundReverted = true;
            }
        }

        // attempt migrateTo if requested and capture whether it reverted
