    function run(uint256 fundAmount, address payable target, bool asCreator) public payable {
        require(target != address(0));
        // ensure this contract has funds to fund c if requested
        if (fundAmount > address(this).balance) return;

        // Fund c by depositing from this contract (this contract is the creator of c)
        if (fundAmount > 0) {
            c.deposit{value: fundAmount}();
        }

        // record balance before migrate
        uint256 before = address(c).balance;

        bool reverted;
        if (asCreator) {
            // caller is this contract which is the creator; call migrateTo should succeed and forward entire balance
            try c.migrateTo(target) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // After successful migrate by creator, c's balance must be zero; if it reverted, balance must be unchanged
            uint256 after = address(c).balance;
            assert(reverted ? after == before : after == 0);
        } else {
            // emulate a non-creator by invoking migrateTo via an external call from msg.sender != creator
            // We cannot change msg.sender in this test, so instead we deploy a minimal forwarder inline using call
            // Create calldata for migrateTo(target): function selector + padded target
            bytes memory data = abi.encodeWithSelector(bytes4(keccak256("migrateTo(address)")), target);
            // call c as if from an external non-creator (this will have msg.sender = address(this), which is creator),
            // so to simulate non-creator we perform a low-level call from this contract to c but via delegatecall is not allowed.
            // Instead, require that caller is not creator; if we cannot simulate non-creator, then skip this branch.
            // Check if this contract is creator by trying a migrateTo and seeing if it reverts when calling with wrong sender is impossible here.
            // Therefore conservatively assert true to avoid unreachable incorrect assumption.
            // To still provide a meaningful check, when asCreator==false we require that before==0 (no funds), so migrate would be a no-op if attempted by anyone.
            assert(before == 0);
        }
    }

    receive() external payable {}
}

