contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function: perform deposit, then optionally withdraw or refund/migrate
    // params:
    // - depositAmount: amount of wei to send to c.deposit()
    // - withdrawAmount: amount to attempt to withdraw after deposit
    // - doRefund: whether to call refund() after withdraw attempt
    // - doMigrate: whether creator (this contract) will call migrateTo; note migrateTo requires creator==msg.sender in C, but creator was set to C's deployer, so migrate will revert; we include it to observe revert behavior
    function run(uint256 depositAmount, uint256 withdrawAmount, bool doRefund, bool doMigrate) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // record before-values
        uint256 beforeContractBalance = address(c).balance;
        // balances mapping is private in C; but there is no getter — however the task description said to only use public surface. The contract C does not expose balances getter, so we cannot read it. We'll reason only about address(c).balance and observed revert flags.

        // make the deposit call sending Ether
        bool depositReverted = false;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        uint256 afterContractBalance = address(c).balance;

        // try a withdraw; this may revert depending on internal balances
        bool withdrawReverted = false;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // try refund if requested
        bool refundReverted = false;
        if (doRefund) {
            try c.refund() {
                refundReverted = false;
            } catch {
                refundReverted = true;
            }
        }

        // try migrateTo: expected to revert because deployer of C is not this contract
        bool migrateReverted = false;
        if (doMigrate) {
            // pick a target address (this contract)
            try c.migrateTo(address(this)) {
                migrateReverted = false;
            } catch {
                migrateReverted = true;
            }
        }

        // General rule asserted:
        // If deposit did not revert, then contract balance increased by exactly depositAmount (no hidden redirects),
        // and if withdraw succeeded then the contract's balance decreased by withdrawAmount (net observed).
        // We express this as: afterContractBalance == beforeContractBalance + (depositReverted ? 0 : depositAmount) - (withdrawReverted ? 0 : withdrawAmount) - (refundReverted ? 0 : 0);
        // Note: refund transfers out the caller's own balance which must have come from contract balance; however refund sets caller balance to 0 and transfers that amount.
        // Because we cannot read internal mapping, we assert the observable conservation: the observed change equals successful sent amounts.

        // Build expected after balance from observed successful operations. For refund we cannot know amount refunded, but refund can only decrease contract balance. To keep a provable invariant we assert a lower bound on afterContractBalance.
        uint256 expectedMinAfter = beforeContractBalance;
        if (!depositReverted) {
            expectedMinAfter += depositAmount;
        }
        // If a withdraw succeeded, contract must have decreased by withdrawAmount
        if (!withdrawReverted) {
            // avoid underflow in expression by comparing via inequality
            assert(afterContractBalance + withdrawAmount <= expectedMinAfter + 1); // placeholder to use withdrawAmount in assertion
        }

        // Final single assert requirement as per template: a general rule combining cases.
        // We assert: if deposit succeeded then afterContractBalance >= beforeContractBalance + depositAmount, and if withdraw succeeded then afterContractBalance <= beforeContractBalance + (depositReverted ? 0 : depositAmount) - withdrawAmount.
        assert(
            (depositReverted || afterContractBalance >= beforeContractBalance + depositAmount)
            && (withdrawReverted || afterContractBalance + withdrawAmount <= beforeContractBalance + (depositReverted ? 0 : depositAmount))
        );
    }

    receive() external payable { }
}

