contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot directly read the internal mapping balances (it's not public),
    // so we observe effects on address balances and use refund's semantics.
    // The test: optionally deposit some Ether into c, then call refund; if refund
    // does not revert then c's balance decreases by the refunded amount,
    // this contract's balance increases by that amount, and subsequent refund
    // yields no further transfers (i.e., recorded balance becomes zero).
    function run(uint256 depositAmount) public payable {
        // Ensure this contract has the funds to deposit if requested
        require(address(this).balance >= depositAmount);

        // Record balances before any interaction
        uint256 contractBalBefore = address(c).balance;
        uint256 ourBalBefore = address(this).balance;

        // Optionally deposit into c to create a refundable balance for this contract
        if (depositAmount > 0) {
            // deposit must be a top-level call
            c.deposit{value: depositAmount}();
        }

        // After deposit (or not), record balances prior to refund
        uint256 contractBalPreRefund = address(c).balance;
        uint256 ourBalPreRefund = address(this).balance;

        // Attempt refund and capture whether it reverted
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        // Balances after refund attempt
        uint256 contractBalAfter = address(c).balance;
        uint256 ourBalAfter = address(this).balance;

        // To check that recorded balance was zeroed, call refund again and see that it transfers nothing
        bool secondReverted;
        uint256 ourBalBeforeSecond = ourBalAfter;
        try c.refund() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint256 ourBalAfterSecond = address(this).balance;
        uint256 contractBalAfterSecond = address(c).balance;

        // Assert the general rule: if the first refund did not revert then
        // 1) the contract's balance decreased by exactly the amount we received
        // 2) our balance increased by that same amount
        // 3) a subsequent refund does not transfer any additional Ether (recorded balance became zero)
        // We express (1) and (2) by equality of deltas; (3) by no change between ourBalAfter and ourBalAfterSecond
        assert(refundedReverted || (
            contractBalPreRefund == contractBalAfter + (ourBalAfter - ourBalPreRefund)
            && ourBalAfter == ourBalPreRefund + (contractBalPreRefund - contractBalAfter)
            && !secondReverted
            && ourBalAfterSecond == ourBalBeforeSecond
            && contractBalAfterSecond == contractBalAfter
        ));
    }

    // accept Ether sent to this test contract
    receive() external payable {}
}

