        // 1) refund never increases c's balance (afterRefundC <= afterDepositC).
        // 2) If refund succeeded then the decrease in c's balance equals the increase in this contract's balance.
        //    i.e., afterDepositC - afterRefundC == afterRefundThis - (address(this).balance - (afterRefundThis - 0))
        // To avoid referencing old this.balance directly, compute this contract's balance change by using
        // the known deposit effect: when deposit succeeded, this contract lost `amount`; when deposit reverted, no loss.
        // Let expectedThisAfterDeposit = address(this).balance + (depositReverted ? 0 : 0) ;
        // Simpler: compute this contract's balance change across the refund: deltaThis = afterRefundThis - (address(this).balance - (afterRefundThis - afterRefundThis));
        // But the above is convoluted. Instead observe that the only outgoing before refund was deposit (if not reverted)
        // and only incoming during refund is the refund transfer. We can reason about equality of deltas by relating
        // the pair (afterDepositC - afterRefundC) to (afterRefundThis - (address(this).balance - 0)).

        // Implement the two checks directly without referencing old this balance value except via amount and depositReverted.
        // Let thisBalanceBeforeRefund = address(this).balance - (refundReverted ? 0 : (afterRefundThis - (address(this).balance)));
        // The above is circular, so instead use these equivalent safe conditions:
        // - refund does not increase c's balance: afterRefundC <= afterDepositC
        // - if refund succeeded, then afterDepositC - afterRefundC == afterRefundThis - (address(this).balance - (depositReverted ? 0 : 0))

        // To express the second equality safely, note that the only known incoming to this contract in this function is via refund,
        // so the increase in this contract from just before refund to after refund equals afterRefundThis - (address(this).balance - (afterRefundThis - afterRefundThis));
        // This is getting circular; instead we anchor on observable values: beforeC, afterDepositC, afterRefundC, and afterRefundThis.

        // Simpler formulation used in the assert below:
        // - refund never increases c's balance.
        // - if refund succeeded then (afterDepositC - afterRefundC) == (afterRefundThis - (address(this).balance - (afterRefundThis - afterRefundThis))) which simplifies to equality of the two observed deltas: contract delta and this-contract's increase during refund.

        // We compute this contract's increase during refund by comparing afterRefundThis to the balance that this contract had immediately after deposit.
        // We can reconstruct this contract balance immediately after deposit: afterDepositThis = address(this).balance + (depositReverted ? 0 : amount);
        uint256 afterDepositThis = address(this).balance + (depositReverted ? 0 : amount);
        uint256 thisIncreaseFromRefund;
        if (afterRefundThis >= afterDepositThis) {
            thisIncreaseFromRefund = afterRefundThis - afterDepositThis;
        } else {
            // If it's smaller, set to a large number that won't match contract decrease; this will make equality fail as desired
            thisIncreaseFromRefund = 0;
        }

        uint256 contractDecrease = afterDepositC >= afterRefundC ? afterDepositC - afterRefundC : 0;

        assert((afterRefundC <= afterDepositC) && (refundReverted || contractDecrease == thisIncreaseFromRefund));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will: deposit some funds into c from this contract (if deposit succeeds),
    // then read address(c).balance and try withdraw(amount). We assert that if withdraw
    // does not revert and the amount was allowed (<= recorded balance as per contract's public behaviour),
    // then c's balance decreased by amount and this contract's balance increased by amount.
    // We avoid using arithmetic that can underflow by guarding comparisons.

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // Ensure this test contract has funds to send depositAmount.
        require(address(this).balance >= depositAmount);

        // Record balances before any interaction
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        // Try to deposit into c from this contract; record whether it reverted.
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // After deposit attempt, record balances
        uint256 afterDepositC = address(c).balance;
        uint256 afterDepositThis = address(this).balance;

        // Now attempt withdraw(withdrawAmount). According to C, withdraw requires amount <= balances[msg.sender].
        // We cannot read balances mapping directly, so we observe behavior: if withdraw succeeds then balances reduced and Ether moved.
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint256 afterWithdrawC = address(c).balance;
        uint256 afterWithdrawThis = address(this).balance;

        // contractDecrease is how much c's balance fell during the withdraw step (i.e., afterDepositC - afterWithdrawC)
        uint256 contractDecrease = 0;
        if (afterDepositC >= afterWithdrawC) {
            contractDecrease = afterDepositC - afterWithdrawC;
        }

        // thisIncrease is how much this contract's balance rose during the withdraw step
        uint256 thisIncrease = 0;
        if (afterWithdrawThis >= afterDepositThis) {
            thisIncrease = afterWithdrawThis - afterDepositThis;
        }

        // General rule asserted:
        // If withdraw did NOT revert, then the observed decrease in c's balance equals the observed increase in this contract's balance,
        // and that common amount equals withdrawAmount (i.e., exact transfer of withdrawAmount happened).
        // If withdraw reverted, we make no claim about balances (other than they changed only via earlier deposit).
        assert(withdrawReverted || (contractDecrease == thisIncrease && contractDecrease == withdrawAmount));
    }

    receive() external payable {}
}

