        uint256 cBalAfterDeposit = address(c).balance;
        uint256 recordedBeforeRefund;
        // balances is internal in C so no getter exists; but problem statement allowed auto-generated getters only for public vars — balances is not public. Therefore we must observe effect via refunds/ETH movements. To follow constraints, we won't call a getter that doesn't exist; instead we will reason using c.balance and this contract's balance changes.
        // Record this contract's balance before refund
        uint256 selfBalBeforeRefund = address(this).balance;

        // Call refund and capture whether it reverted
        bool refundReverted;
        try c.refund() {
